                seen.add((r, c))
                stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] != border:
